const { records } = $.input;
if (!records || !Array.isArray(records) || records.length === 0) throw new Error('records must be a non-empty array');
if (records.length > 10) throw new Error('Airtable allows max 10 records per request. Split into batches.');
const formatted = records.map(r => ({ fields: r.fields || r }));
return { records: formatted };

const resp = $.steps.createRecords.response || {};
const created = resp.records || [];
return {
  records: created.map(r => ({ id: r.id, fields: r.fields, createdTime: r.createdTime })),
  count: created.length,
  summary: `Created ${created.length} record${created.length === 1 ? '' : 's'} in ${$.input.tableIdOrName}`
};
